import { forwardRef, type InputHTMLAttributes } from "react";
import { cn } from "../../lib/cn";
import { useFieldContext } from "../field/field";
import "../../styles/input.css";

export type InputSize = "sm" | "md" | "lg";

export interface InputProps extends Omit<InputHTMLAttributes<HTMLInputElement>, "size"> {
  /** Visual size. Matches Button sizes. */
  size?: InputSize;
  /** Marks the input invalid (red ring, aria-invalid). Inside a Field, this is inherited. */
  invalid?: boolean;
}

/**
 * Text input. Inside a <Field>, it gets its id, description, and error
 * wiring automatically. Outside one, it works as a plain input.
 */
export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  { size = "md", invalid, className, id, ...props },
  ref,
) {
  const field = useFieldContext();

  const isInvalid = invalid ?? field?.invalid ?? false;
  const describedBy =
    [props["aria-describedby"], field?.descriptionId, field?.errorId].filter(Boolean).join(" ") ||
    undefined;

  return (
    <input
      ref={ref}
      id={id ?? field?.id}
      aria-invalid={isInvalid || undefined}
      aria-describedby={describedBy}
      data-size={size}
      className={cn("eui-input", `eui-input--${size}`, className)}
      {...props}
    />
  );
});

Input.displayName = "Input";

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

import { createContext, useContext, useId, type HTMLAttributes, type ReactNode } from "react";
import { cn } from "../../lib/cn";
import "../../styles/field.css";

interface FieldContextValue {
  id: string;
  descriptionId: string | undefined;
  errorId: string | undefined;
  invalid: boolean;
}

const FieldContext = createContext<FieldContextValue | null>(null);

/** @internal Used by Input to wire label, description, and error ids. */
export function useFieldContext(): FieldContextValue | null {
  return useContext(FieldContext);
}

export interface FieldProps extends HTMLAttributes<HTMLDivElement> {
  /** Visible label. Rendered as a real <label> bound to the control. */
  label?: ReactNode;
  /** Helper text shown under the control. Linked via aria-describedby. */
  description?: ReactNode;
  /** Error message. Shown in place of nothing; also marks the control invalid. */
  error?: ReactNode;
  /** Marks the control invalid even without an error message. */
  invalid?: boolean;
  /** Overrides the generated control id. */
  id?: string;
}

/**
 * Groups a label, control, description, and error so the accessibility wiring
 * (for/id, aria-describedby, aria-invalid) is correct by default.
 */
export function Field({
  label,
  description,
  error,
  invalid,
  id,
  className,
  children,
  ...rest
}: FieldProps) {
  const generated = useId();
  const baseId = id ?? `eui-field-${generated.replace(/:/g, "")}`;
  const hasError = error !== undefined && error !== null && error !== false && error !== "";
  const isInvalid = invalid ?? hasError;

  const value: FieldContextValue = {
    id: baseId,
    descriptionId: description ? `${baseId}-description` : undefined,
    errorId: hasError ? `${baseId}-error` : undefined,
    invalid: !!isInvalid,
  };

  return (
    <FieldContext.Provider value={value}>
      <div className={cn("eui-field", className)} {...rest}>
        {label ? (
          <label className="eui-field__label" htmlFor={baseId}>
            {label}
          </label>
        ) : null}
        {children}
        {description ? (
          <p id={value.descriptionId} className="eui-field__description">
            {description}
          </p>
        ) : null}
        {hasError ? (
          <p id={value.errorId} className="eui-field__error" role="alert">
            {error}
          </p>
        ) : null}
      </div>
    </FieldContext.Provider>
  );
}

/* Input. The border is a box-shadow ring (no layout cost), so it matches Button's approach.
   Border color is border-strong so the field boundary meets WCAG 3:1 for UI components. */

.eui-input {
  --eui-input-h: 36px;
  --eui-input-fs: 14px;

  display: block;
  width: 100%;
  min-width: 0;
  height: var(--eui-input-h);
  padding: 0 12px;
  border: 0;
  border-radius: var(--eui-radius-base);
  background-color: var(--eui-color-bg);
  color: var(--eui-color-fg);
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-border-strong);
  font-family: inherit;
  font-size: var(--eui-input-fs);
  letter-spacing: -0.006em;
  appearance: none;
}

.eui-input--sm {
  --eui-input-h: 32px;
  --eui-input-fs: 13px;
  padding: 0 10px;
}
.eui-input--md {
  --eui-input-h: 36px;
  --eui-input-fs: 14px;
}
.eui-input--lg {
  --eui-input-h: 44px;
  --eui-input-fs: 15px;
  padding: 0 14px;
}

@media (pointer: coarse) {
  .eui-input--sm {
    --eui-input-h: 40px;
  }
  .eui-input--md {
    --eui-input-h: 44px;
  }
}

.eui-input::placeholder {
  color: var(--eui-color-fg-muted);
  opacity: 1;
}

.eui-input:hover:not(:disabled):not(:focus) {
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-fg-muted);
}

.eui-input:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}

.eui-input[aria-invalid="true"] {
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-danger);
}

.eui-input:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Field: label, description, and error. Layout only; the control is styled in input.css. */

.eui-field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.eui-field__label {
  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  color: var(--eui-color-fg);
  cursor: default;
}

.eui-field__description {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--eui-color-fg-muted);
}

.eui-field__error {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--eui-color-danger);
}
